const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let inputs = [];

rl.on('line', (line) => {
    inputs.push(line.trim());
    if (inputs.length === 2) {
        const strA = inputs[0];
        const a = parseInt(strA, 10);
        const aMod = parseInt(strA.replace(/0/g, ''), 10);

        const strB = inputs[1];
        const b = parseInt(strB, 10);
        const bMod = parseInt(strB.replace(/0/g, ''), 10);

        const c = a + b;
        const cMod = parseInt(c.toString().replace(/0/g, ''), 10);

        if (aMod + bMod === cMod)
            console.log("YES");
        else
            console.log("NO");

        rl.close();
    }
});

